const now = new Date();
const istOffset = 5.5 * 3600000;
const nowIst = new Date(now.getTime() + istOffset);
const todayIst = new Date(Date.UTC(nowIst.getUTCFullYear(), nowIst.getUTCMonth(), nowIst.getUTCDate()));
const yesterdayIst = new Date(todayIst.getTime() - 86400000);
const pad = n => String(n).padStart(2, '0');
const day = yesterdayIst.getUTCFullYear() + '-' + pad(yesterdayIst.getUTCMonth() + 1) + '-' + pad(yesterdayIst.getUTCDate());
const dayFormatted = pad(yesterdayIst.getUTCDate()) + '/' + pad(yesterdayIst.getUTCMonth() + 1) + '/' + yesterdayIst.getUTCFullYear();
return [{ json: { day, dayFormatted } }];

const d = $('Compute Dates').first().json.day;
// Same two mistag patterns as resmed_flagged_tags_webhook.json, scoped to
// yesterday only (this is a daily digest, not a full-history dump) and
// excluding anything already corrected.
const query = `
SELECT cd.txn_id, cd.call_date, cd.start_time, cd.call_type, cd.received_by,
  SUBSTRING_INDEX(cd.note, ',', 1) AS category, cd.recording_url
FROM calls.call_disposition cd
LEFT JOIN calls.call_tag_corrections ctc ON ctc.txn_id = cd.txn_id
WHERE cd.service_id = 1702 AND cd.call_date = '${d}' AND ctc.txn_id IS NULL
  AND (
    (cd.call_type = 'OUTBOUND' AND SUBSTRING_INDEX(cd.note, ',', 1) IN ('Sales Lead','Service Query','Rewards & Registration','Non Customer Query','Other Inbound','Handled by Sales Team'))
    OR
    (cd.call_type = 'INBOUND' AND cd.note LIKE 'OB -%')
  )
ORDER BY cd.received_by, cd.start_time;
`;
return [{ json: { query } }];

const dates = $('Compute Dates').first().json;
const rows = $('Exec Flagged Query').all().map(item => item.json);

// Human-readable description of exactly what's wrong + what the fix should
// look like, so the TL doesn't have to guess what 'flagged' means per row.
function issueText(row) {
  if (row.call_type === 'OUTBOUND') {
    return `Outbound call tagged with an Inbound category ("${row.category}") -- should be one of the "OB - ..." Outbound categories.`;
  }
  return `Inbound call tagged with an Outbound category ("${row.category}") -- should be one of: Sales Lead, Service Query, Rewards & Registration, Non Customer Query, Other Inbound, Handled by Sales Team.`;
}

const byAgent = {};
rows.forEach(row => {
  const agent = (row.received_by || 'Unassigned').split(',')[0].trim();
  if (!byAgent[agent]) byAgent[agent] = [];
  byAgent[agent].push(row);
});
const agents = Object.keys(byAgent).sort();

const cell = 'padding:6px 10px;border:1px solid #999;font-family:Arial,sans-serif;font-size:12px;box-sizing:border-box;vertical-align:top;';
const headerBg = '#DCE6F0';
const agentBg = '#FBE0CE';

let html = '<div style="font-family:Arial,sans-serif;">';
html += '<p style="font-weight:bold;font-style:italic;text-decoration:underline;font-size:14px;">ResMed -- Calls Needing Tag Correction (' + dates.dayFormatted + ')</p>';

if (!agents.length) {
  html += '<p>No mistagged calls found for ' + dates.dayFormatted + '.</p>';
} else {
  html += '<table style="border-collapse:collapse;width:900px;">';
  html += '<tr>'
    + '<td style="' + cell + 'background:' + headerBg + ';font-weight:bold;width:140px;">Transaction ID</td>'
    + '<td style="' + cell + 'background:' + headerBg + ';font-weight:bold;width:80px;">Call Type</td>'
    + '<td style="' + cell + 'background:' + headerBg + ';font-weight:bold;width:100px;">Recording</td>'
    + '<td style="' + cell + 'background:' + headerBg + ';font-weight:bold;">What to Correct</td>'
    + '</tr>';
  agents.forEach(agent => {
    html += '<tr><td colspan="4" style="' + cell + 'background:' + agentBg + ';font-weight:bold;">' + agent + ' (' + byAgent[agent].length + ')</td></tr>';
    byAgent[agent].forEach(row => {
      html += '<tr>'
        + '<td style="' + cell + '">' + row.txn_id + '</td>'
        + '<td style="' + cell + '">' + row.call_type + '</td>'
        + '<td style="' + cell + '">' + (row.recording_url ? '<a href="' + row.recording_url + '">Listen</a>' : '-') + '</td>'
        + '<td style="' + cell + '">' + issueText(row) + '</td>'
        + '</tr>';
    });
  });
  html += '</table>';
}
html += '<div style="margin-top:16px;padding-top:14px;border-top:1px solid #ccc;"><a href="https://automation.openmindhelpline.com/webhook/resmed-send-daily-report" style="display:inline-block;padding:8px 16px;background:#2563eb;color:#ffffff;text-decoration:none;border-radius:4px;font-weight:bold;font-size:13px;">Send ResMed Daily Report Now</a></div>';
html += '</div>';

const subject = 'ResMed - ' + rows.length + ' Call(s) Needing Tag Correction - ' + dates.dayFormatted;
return [{ json: { html, subject, flaggedCount: rows.length } }];
